corrected_code:
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);
const { acmeClient } = require('../lib/acme');
const { db } = require('../db');

async function processSslCertStream() {
  while (true) {
    const batch = await redis.xreadgroup('GROUP', 'ssl-workers', 'c-1', 'BLOCK', 3000, 'STREAMS', 'stream:domains:ssl-provision', '>');
    if (!batch) continue;

    for (const [, messages] of batch) {
      for (const [msgId, fields] of messages) {
        const { domainName, targetTenantId } = JSON.parse(fields[1]);

        const ownership = await db.query(
          'SELECT id FROM tenant_domains WHERE domain = $1 AND tenant_id = $2 AND verified = true',
          [domainName, targetTenantId]
        );
        if (ownership.rowCount === 0) {
          console.error(`Dropped unauthorized SSL request for ${domainName} by tenant ${targetTenantId}`);
          await redis.xack('stream:domains:ssl-provision', 'ssl-workers', msgId);
          continue;
        }

        const cert = await acmeClient.requestCertificate(domainName);
        await db.query(
          'INSERT INTO tenant_ssl_certificates (tenant_id, domain, cert_pem, priv_key) VALUES ($1, $2, $3, $4)',
          [targetTenantId, domainName, cert.certificate, cert.privateKey]
        );
        await redis.xack('stream:domains:ssl-provision', 'ssl-workers', msgId);
      }
    }
  }
}
